from rest_framework import serializers
from .models import Book


class BookSerializer(serializers.ModelSerializer):
    class Meta:
        model = Book
        fields = ["id", "title", "isbn", "cover", "document"]

    def validate_cover(self, value):
        if value is None:
            return value

        # حجم
        max_size = 5 * 1024 * 1024
        if value.size > max_size:
            raise serializers.ValidationError(
                "حجم تصویر نمی‌تواند بیشتر از ۵ مگابایت باشد."
            )

        # نوع فایل
        allowed = ["image/jpeg", "image/png", "image/webp"]
        if value.content_type not in allowed:
            raise serializers.ValidationError(
                "فرمت تصویر باید JPEG، PNG یا WebP باشد."
            )

        # پسوند
        valid_exts = [".jpg", ".jpeg", ".png", ".webp"]
        ext = ""
        for e in valid_exts:
            if value.name.lower().endswith(e):
                ext = e
                break
        if not ext:
            raise serializers.ValidationError(
                "پسوند فایل نامعتبر است."
            )

        return value

    def validate_document(self, value):
        if value is None:
            return value

        max_size = 10 * 1024 * 1024
        if value.size > max_size:
            raise serializers.ValidationError(
                "حجم سند نمی‌تواند بیشتر از ۱۰ مگابایت باشد."
            )

        allowed = ["application/pdf", "application/msword"]
        if value.content_type not in allowed:
            raise serializers.ValidationError(
                "فرمت سند باید PDF یا DOC باشد."
            )

        return value

class Gallery(models.Model):
    title = models.CharField(max_length=200)
    owner = models.ForeignKey("auth.User", on_delete=models.CASCADE)


class GalleryImage(models.Model):
    gallery = models.ForeignKey(
        Gallery, on_delete=models.CASCADE, related_name="images"
    )
    image = models.ImageField(upload_to="galleries/%Y/%m/")
    caption = models.CharField(max_length=200, blank=True)
    order = models.PositiveIntegerField(default=0)

class GalleryImageSerializer(serializers.ModelSerializer):
    class Meta:
        model = GalleryImage
        fields = ["id", "image", "caption", "order"]


class GalleryCreateSerializer(serializers.ModelSerializer):
    images = GalleryImageSerializer(many=True)

    class Meta:
        model = Gallery
        fields = ["id", "title", "images"]

    def validate_images(self, value):
        if not value:
            raise serializers.ValidationError("حداقل یک تصویر لازم است.")
        if len(value) > 20:
            raise serializers.ValidationError("حداکثر ۲۰ تصویر.")
        return value

    def create(self, validated_data):
        images_data = validated_data.pop("images")
        gallery = Gallery.objects.create(**validated_data)
        GalleryImage.objects.bulk_create([
            GalleryImage(gallery=gallery, **img)
            for img in images_data
        ])
        return gallery

import magic   # python-magic
from rest_framework import serializers


class SafeDocumentSerializer(serializers.ModelSerializer):
    class Meta:
        model = SafeDocument
        fields = ["id", "file", "original_name"]
        read_only_fields = ["id", "original_name"]

    def validate_file(self, value):
        # ۱. حجم
        if value.size > 10 * 1024 * 1024:
            raise serializers.ValidationError("حجم فایل بیش از ۱۰ مگابایت.")

        # ۲. نوع محتوای واقعی (نه فقط content_type)
        mime = magic.from_buffer(value.read(2048), mime=True)
        value.seek(0)   # بازگرداندن موقعیت فایل

        allowed = {
            "application/pdf",
            "image/jpeg",
            "image/png",
        }
        if mime not in allowed:
            raise serializers.ValidationError(
                f"فرمت {mime} پشتیبانی نمی‌شود."
            )

        return value

    def create(self, validated_data):
        file = validated_data["file"]
        validated_data["original_name"] = file.name[:255]
        return super().create(validated_data)

